      'This folder already contains synced settings. When sync is turned on, the selected sections will be replaced by the ones in the folder (a settings backup is taken first). Continue?',
      'Dieser Ordner enthält bereits abgeglichene Einstellungen. Beim Einschalten werden die gewählten Bereiche durch die im Ordner ersetzt (vorher wird eine Einstellungssicherung angelegt). Fortfahren?',
      'Ce dossier contient déjà des paramètres synchronisés. À l’activation, les sections choisies seront remplacées par celles du dossier (une sauvegarde des paramètres est faite d’abord). Continuer ?',
