      'Candidates that look like sensors, are duplicates or do not suit the panel are hidden by default (this is a suggestion, separate from the safety rule). Selected ones are always visible.',
      'Kandidaten, die wie Sensoren aussehen, doppelt vorhanden sind oder nicht ins Panel passen, sind standardmäßig ausgeblendet (das ist eine Empfehlung und unabhängig von der Sicherheitsregel). Ausgewählte sind immer sichtbar.',
      'Les candidats qui ressemblent à des capteurs, qui sont en double ou qui ne conviennent pas au panneau sont masqués par défaut (il s’agit d’une suggestion, indépendante de la règle de sécurité). Les éléments sélectionnés sont toujours visibles.',
