      'Windows encryption (safeStorage) is not available; you cannot register because the identifier could not be stored securely.',
      'Die Windows-Verschlüsselung (safeStorage) ist nicht verfügbar; eine Registrierung ist nicht möglich, weil die Kennung nicht sicher gespeichert werden kann.',
