  const en = {};
  const de = {};
  const fr = {};
  const es = {};
  for (const [anahtar, turkce, ingilizce, almanca, fransizca, ispanyolca] of SATIRLAR) {
    tr[anahtar] = turkce;
    en[anahtar] = ingilizce;
    de[anahtar] = almanca;
    fr[anahtar] = fransizca;
    es[anahtar] = ispanyolca;
  }
  return { tr, en, de, fr, es };
